draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // face
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // emotion cloud
  ctx.beginPath();
  ctx.arc(W/2 + 100 * Math.sin(t), H/2, 30 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('HAPPY', W/2 + 100 * Math.sin(t), H/2);

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 - 100 * Math.cos(t), H/2, 30 + 10 * Math.cos(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('I AM', W/2 - 100 * Math.cos(t), H/2 - 20);
  ctx.fillText('HAPPY', W/2 - 100 * Math.cos(t), H/2 + 20);

  ctx.restore();
}
